namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int LoyaltyMinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyCents(subtotalCents, tier);
        var promoCents = PromoCents(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int LoyaltyCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < LoyaltyMinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier), LoyaltyCapCents);

    private static int PromoCents(string? promoCode, int remainingCents) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min(remainingCents / 10, Summer10CapCents),
            _ => 0
        };
}
EOF
